tool_input.command:
cat >> src/pagination.js <<'EOF'

/**
 * Page links for rendering a pager: always 1, totalPages and the pages
 * around `current`, with '...' wherever page numbers are skipped.
 */
export function pageLinks(current, totalPages) {
  const wanted = new Set([1, totalPages, current - 1, current, current + 1]);
  const pages = [...wanted]
    .filter((p) => p >= 1 && p <= totalPages)
    .sort((a, b) => a - b);
  const out = [];
  for (const p of pages) {
    if (out.length && p - out[out.length - 1] > 1) out.push('...');
    out.push(p);
  }
  return out;
}
EOF
